mapper.select:
SELECT TO_CHAR(TO_DATE(sl.execution_yyyymm,'YYYYMM'),'YYYY-MM') AS execution_yyyymm , mm.system_code , mm.module_code , sl.menu_id , mm.menu_name , sl.program_id , pm.program_name , sl.system_service_desc , SUBSTR(sl.system_service_desc,INSTR(sl.system_service_desc, '/', -1) + 1) AS service_name , sl.average_processing_time FROM LGCOM_SYSTEM_SERVICE_LOG_S sl , LGCOM_MENU_M mm , LGCOM_PROGRAM_M pm WHERE sl.execution_yyyymm = REPLACE(#{executionYyyymm},'-','') AND sl.menu_id = mm.menu_id AND sl.program_id = pm.program_id
AND mm.system_code = #{systemCode}
AND mm.module_code = #{moduleCode}
AND sl.menu_id = #{menuId}
AND sl.program_id = #{programId}
AND UPPER(sl.system_service_desc) LIKE '%' || UPPER(#{serviceDesc}) || '%'
ORDER BY sl.execution_yyyymm,mm.system_code,mm.module_code,sl.menu_id,pm.program_id,sl.system_service_desc
